<form method="post" enctype="multipart/form-data"><h1>Profile</h1><?= csrf_field() ?><?php foreach($errors as $er): ?><p><?= e($er) ?></p><?php endforeach; ?><input name="username" value="<?= e($user['username']) ?>" required><input type="email" name="email" value="<?= e($user['email']) ?>" required><input type="file" name="profile_picture" accept="image/jpeg,image/png,image/webp"><label><input type="checkbox" name="remove_picture" value="1"> Remove profile picture</label><button>Save</button></form>
